<template><div class="page"><div class="crumb"><button @click="router.back()">课程作业</button><span>›</span><strong>{{ detail?.title || '作业详情' }}</strong></div><div v-if="errorMessage" class="error">{{ errorMessage }}</div><section v-if="detail" class="panel"><header><div><p>ASSIGNMENT DETAIL</p><h1>{{ detail.title }}</h1><span>截止时间：{{ date(detail.deadline) }}</span></div><b class="forming">{{ formation ? '组队中' : '可提交' }}</b></header><div class="content"><section class="requirements"><h2>作业要求</h2><p>{{ detail.description || '暂无详细作业说明' }}</p></section><section v-if="formation" class="formation"><div><h2>组队中</h2><p>加入小组后立即生效。组队期结束后小组自动锁定，不能再更换。</p></div><div class="join"><button class="primary" :disabled="working || detail.groupName" @click="createGroup">{{ detail.groupName ? '已加入小组' : '创建小组' }}</button><span>或选择小组</span><select v-model="selectedGroup" :disabled="working || detail.groupName"><option value="">请选择小组</option><option v-for="group in groups" :key="group.id" :value="group.groupNo" :disabled="group.memberCount >= group.maxMembers">{{ group.groupNo }}（{{ group.memberCount }}人）</option></select><button class="secondary" :disabled="working || !selectedGroup || detail.groupName" @click="joinGroup">加入小组</button></div></section><section><h2>我的小组</h2><div v-if="detail.groupName" class="team"><strong>{{ detail.groupName }}</strong><span v-for="member in detail.members" :key="member.studentId">{{ member.name }}（{{ member.studentNo }}）</span><button v-if="formation" class="leave" @click="leaveGroup">取消，重新组队</button><em v-else>小组已锁定</em></div><el-empty v-else description="暂未加入小组"/></section><section v-if="!formation"><h2>提交作业</h2><textarea v-model="form.content" placeholder="填写作业内容"></textarea><input v-model="form.filePath" placeholder="附件路径"/><textarea v-model="form.note" placeholder="备注（可选）"></textarea><button class="primary" :disabled="saving" @click="submit">{{ saving ? '提交中…' : '提交作业' }}</button></section></div></section><div v-else class="loading">正在加载…</div></div></template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { createStudentGroup,getAssignment,getAssignmentGroups,joinStudentGroup,leaveStudentGroup,submitAssignment } from '@/api/student';import { getErrorMessage } from '@/api/response'
const route=useRoute();const router=useRouter();const detail=ref(null);const groups=ref([]);const selectedGroup=ref('');const errorMessage=ref('');const working=ref(false);const saving=ref(false);const form=reactive({content:'',filePath:'',note:''});const formation=computed(()=>detail.value?.publishedAt&&Date.now()-new Date(detail.value.publishedAt).getTime()<172800000);const date=value=>value?new Date(value).toLocaleString('zh-CN'):'未设置';const load=async()=>{detail.value=await getAssignment(route.params.assignmentId);groups.value=await getAssignmentGroups(route.params.assignmentId);form.content=detail.value.content||'';form.filePath=detail.value.filePath||'';form.note=detail.value.submitNote||''};const createGroup=async()=>{working.value=true;try{await createStudentGroup(route.params.assignmentId);await load();ElMessage.success('小组创建成功')}catch(error){errorMessage.value=getErrorMessage(error,'创建小组失败')}finally{working.value=false}};const joinGroup=async()=>{working.value=true;try{await joinStudentGroup(route.params.assignmentId,Number(selectedGroup.value));await load();ElMessage.success('加入小组成功')}catch(error){errorMessage.value=getErrorMessage(error,'加入小组失败')}finally{working.value=false}};const leaveGroup=async()=>{if(!confirm('确定退出当前小组并重新组队吗？'))return;try{await leaveStudentGroup(route.params.assignmentId);await load();ElMessage.success('已退出小组')}catch(error){errorMessage.value=getErrorMessage(error,'退出小组失败')}};const submit=async()=>{saving.value=true;try{await submitAssignment(route.params.assignmentId,form);await load();ElMessage.success('作业已提交')}catch(error){errorMessage.value=getErrorMessage(error,'提交失败')}finally{saving.value=false}};onMounted(async()=>{try{await load()}catch(error){errorMessage.value=getErrorMessage(error,'作业详情加载失败')}})
</script>
<style scoped>.page{max-width:980px;margin:0 auto}.crumb{display:flex;gap:8px;margin-bottom:24px;color:#8795a6;font-size:14px}.crumb button{border:0;background:none;color:inherit;cursor:pointer}.crumb strong{color:#263b53}.panel{overflow:hidden;border-radius:9px;background:#fff;box-shadow:0 3px 12px #263b5310}header{display:flex;justify-content:space-between;padding:26px;border-bottom:1px solid #edf1f4}header p{margin:0 0 8px;color:#6b9ed8;font-size:11px;letter-spacing:1.5px}h1{margin:0 0 8px;color:#263b53}header span{color:#8795a6;font-size:13px}.forming{display:inline-block;height:max-content;padding:6px 13px;border-radius:99px;color:#356798;background:#eaf2fa;font-size:12px}.content{padding:26px}.content h2{margin:0 0 12px;color:#334155;font-size:17px}.requirements{padding-bottom:22px}.requirements p{margin:0;white-space:pre-wrap;color:#64748b;line-height:1.8}.formation{margin:0 0 24px;padding:18px;border:1px solid #d9e8f5;border-radius:8px;background:#f7fbff}.formation h2{margin-bottom:7px}.formation p{margin:0;color:#8795a6;font-size:13px}.join{display:flex;align-items:center;gap:10px;margin-top:18px}.join select{width:170px;padding:10px;border:1px solid #dbe3ea;border-radius:6px;color:#52657a;background:#fff}.primary,.secondary,.leave{padding:10px 17px;border:0;border-radius:6px;cursor:pointer}.primary{color:#fff;background:#356798}.secondary{color:#356798;background:#eaf2fa}.leave{color:#b42318;background:#fff5f5}.primary:disabled,.secondary:disabled{opacity:.5;cursor:not-allowed}.team{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-bottom:25px}.team strong,.team span{padding:9px 13px;border-radius:6px;color:#52657a;background:#f3f7fa}.team strong{color:#356798;background:#eaf2fa}textarea,input{box-sizing:border-box;width:100%;margin-bottom:12px;padding:12px;border:1px solid #dbe3ea;border-radius:6px;outline:none;font:inherit}textarea{min-height:100px;resize:vertical}.error{margin-bottom:16px;padding:12px;color:#b42318;background:#fff5f5}.loading{text-align:center;color:#8795a6;padding:40px}@media(max-width:700px){.join{align-items:stretch;flex-direction:column}.join select{width:100%}.leave{width:100%}}</style>
